//! #417: the MB-SMF's N2 MBS transfers, generated codec against the
//! hand-written `nextgcore-ngap::mbs_transfer` codec it replaced, kept here (as
//! a dev-dependency only) as the ORACLE. Builders: the generated bytes are the
//! hand-written bytes for every input. Parsers: on every transfer the
//! hand-written encoder produces, the generated parse reads the TMGI the
//! hand-written decoder reads.

use super::*;
use nextgcore_asn1c::ngap::cause::{Cause, CauseMisc, CauseNas, CauseRadioNetwork, CauseTransport};
use nextgcore_ngap::mbs_transfer as hw;
use nextgcore_ngap::transfer as hwt;
use proptest::prelude::*;

fn hw_session_id((plmn, service): NgapTmgi) -> hw::MbsSessionId {
    hw::MbsSessionId::new(plmn, service)
}

/// The pre-#417 Setup Response builder in `amf_shared_delivery_setup`.
fn hw_setup_response(
    tmgi: NgapTmgi,
    tunnel: SharedMulticastTunnel,
    qfi: u8,
    five_qi: u8,
) -> nextgcore_ngap::NgapResult<Vec<u8>> {
    hw::MbsDistributionSetupResponseTransfer {
        mbs_session_id: hw_session_id(tmgi),
        mbs_area_session_id: None,
        shared_ngu_multicast_tnl_information: Some(hw::SharedNguMulticastTnlInformation {
            ip_multicast_address: hwt::TransportLayerAddress::from_ipv4(tunnel.multicast_address),
            ip_source_address: hwt::TransportLayerAddress::from_ipv4(tunnel.source_address),
            gtp_teid: tunnel.teid.to_be_bytes(),
        }),
        mbs_qos_flows_to_be_setup_list: vec![hw::MbsQosFlowsToBeSetupItem {
            mbs_qos_flow_identifier: qfi,
            mbs_qos_flow_level_qos_parameters: hwt::QosFlowLevelQosParameters {
                qos_characteristics: hwt::QosCharacteristics::NonDynamic5qi(
                    hwt::NonDynamic5qiDescriptor::new(u16::from(five_qi)),
                ),
                allocation_and_retention_priority: hwt::AllocationAndRetentionPriority {
                    priority_level_arp: 8,
                    pre_emption_capability: hwt::PreEmptionCapability::ShallNotTriggerPreEmption,
                    pre_emption_vulnerability: hwt::PreEmptionVulnerability::NotPreEmptable,
                },
                gbr_qos_information: None,
                reflective_qos_attribute: false,
                additional_qos_flow_information: false,
            },
        }],
        mbs_session_status: hw::MbsSessionStatus::Activated,
    }
    .encode()
}

fn tmgi() -> impl Strategy<Value = NgapTmgi> {
    (any::<[u8; 3]>(), any::<[u8; 3]>())
}

fn hw_tunnel() -> impl Strategy<Value = hwt::UpTransportLayerInformation> {
    (any::<u32>(), any::<[u8; 4]>()).prop_map(|(teid, addr)| {
        hwt::UpTransportLayerInformation::GtpTunnel(hwt::GtpTunnel {
            transport_layer_address: hwt::TransportLayerAddress::from_ipv4(addr),
            gtp_teid: teid.to_be_bytes(),
        })
    })
}

fn hw_cause() -> impl Strategy<Value = Cause> {
    prop_oneof![
        Just(Cause::Nas(CauseNas::NormalRelease)),
        Just(Cause::Nas(CauseNas::Unspecified)),
        Just(Cause::Transport(
            CauseTransport::TransportResourceUnavailable
        )),
        Just(Cause::RadioNetwork(CauseRadioNetwork::Unspecified)),
        Just(Cause::Misc(CauseMisc::Unspecified)),
    ]
}

/// MBS-SessionID with or without its 44-bit NID.
fn hw_mbs_session_id() -> impl Strategy<Value = hw::MbsSessionId> {
    (tmgi(), proptest::option::of(0u64..(1 << 44))).prop_map(|(t, nid)| hw::MbsSessionId {
        nid,
        ..hw_session_id(t)
    })
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]

    #[test]
    fn setup_response_transfer_is_the_hand_written_bytes(
        t in tmgi(),
        (multicast_address, source_address, teid) in (any::<[u8; 4]>(), any::<[u8; 4]>(), any::<u32>()),
        qfi in 0u8..=MAX_QFI,
        five_qi in any::<u8>(),
    ) {
        let tunnel = SharedMulticastTunnel { multicast_address, source_address, teid };
        prop_assert_eq!(
            setup_response_transfer(t, tunnel, qfi, five_qi).unwrap(),
            hw_setup_response(t, tunnel, qfi, five_qi).unwrap()
        );
    }

    #[test]
    fn setup_unsuccessful_transfer_is_the_hand_written_bytes(t in tmgi()) {
        let old = hw::MbsDistributionSetupUnsuccessfulTransfer {
            mbs_session_id: hw_session_id(t),
            mbs_area_session_id: None,
            cause: Cause::Transport(CauseTransport::TransportResourceUnavailable),
            criticality_diagnostics: None,
        }
        .encode()
        .unwrap();
        prop_assert_eq!(setup_unsuccessful_transfer(t).unwrap(), old);
    }

    /// Every optional member the hand-written encoder can write, the TAI MBS
    /// Support List extension (id 441, criticality ignore) included. TS 38.413
    /// V17.9 does not define 441 -- the extension set is empty there -- so the
    /// generated parse skips it as an unknown `ignore` extension; the TMGI is
    /// unaffected either way.
    #[test]
    fn setup_request_tmgi_parses_as_the_hand_written_decoder_reads_it(
        id in hw_mbs_session_id(),
        area in proptest::option::of(any::<u16>()),
        tnl in proptest::option::of(hw_tunnel()),
        tais in proptest::option::of(proptest::collection::vec(
            (any::<[u8; 3]>(), any::<[u8; 3]>()).prop_map(|(plmn_identity, tac)| hw::TaiMbsSupportItem { plmn_identity, tac }),
            1..=3,
        )),
    ) {
        let bytes = hw::MbsDistributionSetupRequestTransfer {
            mbs_session_id: id,
            mbs_area_session_id: area,
            shared_ngu_unicast_tnl_information: tnl,
            tai_mbs_support_list: tais,
        }
        .encode()
        .unwrap();
        let old = hw::MbsDistributionSetupRequestTransfer::decode(&bytes).unwrap().mbs_session_id;
        prop_assert_eq!(
            parse_setup_request_tmgi(&bytes).unwrap(),
            (old.plmn_identity, old.mbs_service_id)
        );
    }

    #[test]
    fn release_request_tmgi_parses_as_the_hand_written_decoder_reads_it(
        id in hw_mbs_session_id(),
        area in proptest::option::of(any::<u16>()),
        tnl in proptest::option::of(hw_tunnel()),
        cause in hw_cause(),
    ) {
        let bytes = hw::MbsDistributionReleaseRequestTransfer {
            mbs_session_id: id,
            mbs_area_session_id: area,
            shared_ngu_unicast_tnl_information: tnl,
            cause,
        }
        .encode()
        .unwrap();
        let old = hw::MbsDistributionReleaseRequestTransfer::decode(&bytes).unwrap().mbs_session_id;
        prop_assert_eq!(
            parse_release_request_tmgi(&bytes).unwrap(),
            (old.plmn_identity, old.mbs_service_id)
        );
    }

    /// The hand-written decoder reads the generated Setup Response bytes back to
    /// the values they were built from.
    #[test]
    fn the_hand_written_decoder_reads_the_generated_setup_response(
        t in tmgi(),
        (multicast_address, source_address, teid) in (any::<[u8; 4]>(), any::<[u8; 4]>(), any::<u32>()),
        qfi in 0u8..=MAX_QFI,
    ) {
        let tunnel = SharedMulticastTunnel { multicast_address, source_address, teid };
        let back = hw::MbsDistributionSetupResponseTransfer::decode(
            &setup_response_transfer(t, tunnel, qfi, 9).unwrap(),
        )
        .unwrap();
        prop_assert_eq!(back.mbs_session_id, hw_session_id(t));
        let tnl = back.shared_ngu_multicast_tnl_information.unwrap();
        prop_assert_eq!(tnl.gtp_teid, teid.to_be_bytes());
        prop_assert_eq!(tnl.ip_multicast_address.octets, multicast_address.to_vec());
        prop_assert_eq!(back.mbs_qos_flows_to_be_setup_list[0].mbs_qos_flow_identifier, qfi);
    }
}

/// A Setup Request whose only extension is relabelled to an id no release
/// defines (9): skipped at `ignore` and `notify`, refused at `reject` -- by the
/// generated parse and by the oracle alike.
#[test]
fn an_unknown_extension_is_skipped_unless_its_criticality_is_reject() {
    let tmgi = ([0x02, 0xf8, 0x39], [0x00, 0x00, 0x01]);
    let bytes = hw::MbsDistributionSetupRequestTransfer {
        mbs_session_id: hw_session_id(tmgi),
        mbs_area_session_id: None,
        shared_ngu_unicast_tnl_information: None,
        tai_mbs_support_list: Some(vec![hw::TaiMbsSupportItem {
            plmn_identity: [0x02, 0xf8, 0x39],
            tac: [0, 0, 1],
        }]),
    }
    .encode()
    .unwrap();
    // The one-entry container: count - 1 (16 bits, aligned), then id 441.
    let at = bytes
        .windows(4)
        .position(|w| w == [0x00, 0x00, 0x01, 0xb9])
        .expect("the TAI MBS Support List entry");
    for (criticality, accepted) in [(0u8, false), (1, true), (2, true)] {
        let mut b = bytes.clone();
        b[at + 2..at + 4].copy_from_slice(&9u16.to_be_bytes());
        b[at + 4] = (b[at + 4] & 0x3f) | (criticality << 6);
        assert_eq!(
            parse_setup_request_tmgi(&b).ok(),
            accepted.then_some(tmgi),
            "criticality {criticality}"
        );
        assert_eq!(
            hw::MbsDistributionSetupRequestTransfer::decode(&b).is_ok(),
            accepted,
            "the oracle, criticality {criticality}"
        );
    }
}

/// The existing hand-derived goldens in main.rs's tests, read by the parsers.
#[test]
fn the_golden_requests_parse() {
    // GOLDEN_MBS_SETUP_REQ: TMGI 208/93 + 000001, area 1, GTP tunnel.
    let setup = [
        0x60, 0x02, 0xF8, 0x39, 0x00, 0x00, 0x01, 0x00, 0x00, 0x01, 0x01, 0xF0, 0x0A, 0x01, 0x02,
        0x03, 0x00, 0x00, 0x30, 0x39,
    ];
    assert_eq!(
        parse_setup_request_tmgi(&setup).unwrap(),
        ([0x02, 0xF8, 0x39], [0x00, 0x00, 0x01])
    );
    // GOLDEN_MBS_REL_REQ: TMGI 208/93 + C10202, nas/normal-release.
    let release = [0x00, 0x02, 0xF8, 0x39, 0xC1, 0x02, 0x02, 0x40];
    assert_eq!(
        parse_release_request_tmgi(&release).unwrap(),
        ([0x02, 0xF8, 0x39], [0xC1, 0x02, 0x02])
    );
}

#[test]
fn a_qfi_past_63_is_refused_as_before() {
    let tunnel = SharedMulticastTunnel {
        multicast_address: [232, 0, 0, 1],
        source_address: [10, 0, 0, 1],
        teid: 1,
    };
    assert!(hw_setup_response((Default::default(), Default::default()), tunnel, 64, 9).is_err());
    assert!(
        setup_response_transfer((Default::default(), Default::default()), tunnel, 64, 9).is_err()
    );
}
